public sealed class History<T> {          // the last cap values, old ones get overwritten
    readonly T[] buf;
    readonly uint mask;
    uint tail;                              // total writes; never wraps

    public History(int capPow2) { buf = new T[capPow2]; mask = (uint)capPow2 - 1; }

    public int Count => (int)Math.Min(tail, (uint)buf.Length);

    public void Push(T value) => buf[tail++ & mask] = value;

    public T Ago(int i) => buf[(tail - 1 - (uint)i) & mask];   // 0 is the latest, i < Count
}

