pool = new ObjectPool<Bullet>(
    createFunc: () => Instantiate(prefab),
    actionOnGet: b => { b.gameObject.SetActive(true); b.inPool = false; },
    actionOnRelease: b => b.gameObject.SetActive(false),
    actionOnDestroy: b => Destroy(b.gameObject),
    collectionCheck: true,                 // catches a double Release, but only in the Editor
    defaultCapacity: 64, maxSize: 512);

public void Despawn(Bullet b) {
    if (b.inPool) return;                  // already pooled: the second call (timer after a hit) is ignored
    b.inPool = true;
    pool.Release(b);
}
